const groups=['Christians','Muslims','Hindus','Buddhists','Jews','Other','No religion'];
const labels={Christians:'Cristianismo',Muslims:'Islam',Hindus:'Hinduismo',Buddhists:'Budismo',Jews:'Judaísmo',Other:'Otras religiones','No religion':'Sin afiliación'};
const colors={Christians:'#4979a8',Muslims:'#15907b',Hindus:'#dc8f32',Buddhists:'#8c65aa',Jews:'#cf5970',Other:'#73836b','No religion':'#7c8792'};
const escDefault=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function initMapThemes({map,L,root,esc=escDefault}){
 let geo,religion,politics,layer,mode,error='';
 const $=id=>root.querySelector('#'+id);
 const safe=esc;
 const link=(u,t)=>'<a href="'+safe(u)+'" target="_blank" rel="noopener noreferrer">'+safe(t)+' ↗</a>';
 const iso=f=>{const p=f.properties||{},code=p.ISO_A3_EH||p.ISO_A3||p.ADM0_A3;return code==='-99'?p.ADM0_A3_US||p.ADM0_A3:code;};
 const clean=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
 async function load(){if(geo)return;try{const rs=await Promise.all(['/data/world-country-boundaries.geojson','/data/religious-composition-2020.json','/data/election-vote-orientation-ppeg-2025.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error();return r.json()})));geo=rs[0];religion=rs[1];politics=rs[2];error='';}catch{error='No se pudieron cargar las capas. Intenta de nuevo.';}}
 function item(f){const code=iso(f);return mode==='religion'?religion.religions[code]:politics.countries[code];}
 function style(f){const d=item(f);let fill='#c9cfcc',op=.4;if(mode==='religion'&&d){fill=colors[d.dominant];op=.8;}if(mode==='politics'&&d&&d.classified>=20){const ratio=d.left/(d.left+d.right||1);fill=ratio>=.6?'#4387c4':ratio<=.4?'#c9605b':'#9b7a9e';op=.35+.5*Math.min(1,d.classified/65);}return {color:'#fff',weight:.7,fillColor:fill,fillOpacity:op};}
 function detail(f){const p=f.properties||{},d=item(f),name=safe(p.NAME||p.ADMIN||d?.country||iso(f));if(mode==='religion'){let html='<span class="eyebrow">COMPOSICIÓN ESTIMADA · 2020</span><h2>'+name+'</h2>';if(!d)html+='<p>Sin dato para este país en la fuente.</p>';else{const sorted=groups.map(k=>[k,d.shares[k]]).sort((a,b)=>b[1]-a[1]);html+='<p>Grupo con mayor proporción estimada: <strong>'+safe(labels[d.dominant])+' · '+sorted[0][1].toFixed(1)+'%</strong></p><div class="map-theme-bars">'+sorted.map(x=>'<div><span>'+safe(labels[x[0]])+'</span><b>'+x[1].toFixed(1)+'%</b><i><em style="width:'+Math.max(0,Math.min(100,x[1]))+'%;background:'+colors[x[0]]+'"></em></i></div>').join('')+'</div><p>Estimación nacional, no describe diferencias entre comunidades dentro del país.</p>';}html+='<p>'+link(religion.url,'Pew / Our World in Data')+' · '+link('https://www.naturalearthdata.com/','Límites: Natural Earth')+'</p>';return html;}
 let html='<span class="eyebrow">VOTO PARLAMENTARIO · '+safe(d?.date||'SIN DATO')+'</span><h2>'+name+'</h2>';if(!d)html+='<p>Sin clasificación electoral respaldada en esta fuente.</p>';else html+='<p>Votos en la última elección parlamentaria disponible en PPEG.</p><div class="map-theme-bars"><div><span>Ecologistas, socialistas y socialdemócratas (izquierda)</span><b>'+d.left.toFixed(1)+'%</b><i><em style="width:'+d.left+'%;background:#4387c4"></em></i></div><div><span>Conservadores y nacionalistas (derecha)</span><b>'+d.right.toFixed(1)+'%</b><i><em style="width:'+d.right+'%;background:#c9605b"></em></i></div><div><span>Familias no clasificadas</span><b>'+d.unclassified.toFixed(1)+'%</b><i><em style="width:'+d.unclassified+'%;background:#9ca7a4"></em></i></div></div><p>La clasificación corresponde a familias partidarias, no a cada votante. Liberal, democratacristiano, agrario, regional, independiente, alianza o ausente se deja sin clasificar.</p>';html+='<p>'+link(politics.url,'PPEG · WZB Berlin')+' · '+link('https://manifesto-project.wzb.eu/','Comparative Manifesto Project')+' · '+link('https://www.naturalearthdata.com/','Límites: Natural Earth')+'</p>';return html;
 }
 function draw(query,category){if(layer)map.removeLayer(layer);const rows=(geo.features||[]).filter(f=>{const p=f.properties||{},name=p.NAME||p.ADMIN||'',d=item(f);return clean(name+' '+iso(f)).includes(clean(query))&&(mode!=='religion'||category==='all'||d?.dominant===category);});layer=L.geoJSON({type:'FeatureCollection',features:rows},{style,onEachFeature:(f,l)=>{l.bindTooltip((f.properties.NAME||f.properties.ADMIN||'País')+(mode==='religion'&&item(f)?' · '+labels[item(f).dominant]:''));l.on({mouseover:e=>e.target.setStyle({weight:1.8,color:'#253e37'}),mouseout:e=>layer.resetStyle(e.target),click:()=>{ $('map-context').innerHTML=detail(f);if(matchMedia('(max-width:900px)').matches)$('map-context').scrollIntoView({behavior:'smooth',block:'start'});}});}}).addTo(map);
 const mapped=rows.filter(f=>{const d=item(f);return !!d&&(mode!=='politics'||d.classified>=20);}).length,missing=rows.length-mapped;
 $('map-catalog-title').textContent=mode==='religion'?'Credos por país':'Orientación del voto';$('map-layer-stamp').textContent=mode==='religion'?'Composición religiosa estimada · 2020 · fuente Pew Research Center':'Voto en la última elección parlamentaria disponible · PPEG 2025v1 · datos hasta octubre de 2025';
 $('map-legend').innerHTML=mode==='religion'?groups.map(k=>'<span><i style="background:'+colors[k]+'"></i>'+safe(labels[k])+'</span>').join('')+'<span><i style="background:#c9cfcc"></i>Sin dato</span>':'<span><i style="background:#4387c4"></i>Izquierda</span><span><i style="background:#9b7a9e"></i>Mixto</span><span><i style="background:#c9605b"></i>Derecha</span><span><i style="background:#c9cfcc"></i>Sin clasificación</span>';
 $('count').textContent=mapped+' con datos · '+missing+' sin clasificación';$('map-results').textContent=error||rows.length+' países/territorios; '+missing+' sin datos suficientes.';
 $('map-list').innerHTML=rows.filter(f=>{const d=item(f);return d&&(mode!=='politics'||d.classified>=20);}).map(f=>{const d=item(f),p=f.properties||{},name=p.NAME||p.ADMIN;return '<button class="map-result" data-theme-country="'+safe(iso(f))+'"><span>'+(mode==='religion'?safe(labels[d.dominant]):safe(d.date))+'</span><strong>'+safe(name)+'</strong><small>'+(mode==='religion'?'Estimación nacional 2020':'Izq. '+d.left.toFixed(1)+'% · Der. '+d.right.toFixed(1)+'%')+'</small></button>';}).join('')+'<button class="map-result" data-theme-source><strong>Fuente, cobertura y método</strong></button>';
 $('map-list').querySelectorAll('[data-theme-country]').forEach(b=>b.onclick=()=>{const f=rows.find(x=>iso(x)===b.dataset.themeCountry);if(f)$('map-context').innerHTML=detail(f);});$('map-list').querySelector('[data-theme-source]').onclick=()=>{$('map-context').innerHTML=mode==='religion'?'<h2>Fuente, fecha y cobertura</h2><p>Estimaciones Pew 2020; 201 países y territorios, derivadas de más de 2.700 censos y encuestas. El gris identifica zonas fuera del conjunto.</p>'+link(religion.url,'Pew / Our World in Data'):'<h2>Fuente, fecha y cobertura</h2><p>PPEG 2025v1 contiene resultados parlamentarios en 73 países hasta octubre de 2025. Para cada país se muestra su elección más reciente dentro del conjunto.</p><p>Familias izquierda: ecologista, socialista y socialdemócrata. Derecha: conservadora y nacionalista. Los demás partidos no se asignan sin base suficiente. El gris significa falta de datos o baja fracción clasificada.</p>'+link(politics.url,'PPEG / WZB Berlin')+'<p>Geometrías: Natural Earth, escala 1:110m.</p>';};const bounds=layer.getBounds();if(bounds.isValid())map.fitBounds(bounds,{padding:[8,8],maxZoom:2,animate:false});
 }
 async function render(next,query='',category='all'){mode=next;await load();if(geo)draw(query,category);else{$('map-results').textContent=error;}}
 return {render};
}
